Ref = Tuple[str, int]
Call = Tuple[str, str, list]


class IFCLogicalUnknown(str):
    """STEP logical UNKNOWN, distinguished from a literal string value."""
    pass


@dataclass
class IFCFastEntity:
    id: int
    type: str
    args: list

    def is_a(self, name: Optional[str] = None):
        if name is None:
            return self.type
        return self.type.lower() == str(name).lower()

    def __repr__(self):
        return f"#{self.id}={self.type}(...)"

@dataclass
class IFCModel:
    """
    Stores one parsed IFC document in memory.

    The model owns the parsed ``IFCFastEntity`` dictionary together with source
    metadata and caches that can be reused by subsequent IFC operations. The
    input entity dictionary is retained by reference rather than copied so that
    future semantic and exporter operations can modify one shared in-memory
    model.

    Parameters
    ----------
    entities : dict
        Parsed IFC entities keyed by STEP id.
    sourcePath : str , optional
        Original IFC path, when known. Default is None.
    schema : str , optional
        IFC schema identifier, such as ``IFC2X3`` or ``IFC4``. Default is None.
    header : str , optional
        Preserved STEP HEADER section. Default is None.
    modelId : str , optional
        Unique identifier for this in-memory model. A UUID is generated by
        default.
    revision : int , optional
        In-memory model revision. Default is 0.
    dirty : bool , optional
        Indicates whether the model differs from its source. Default is False.

    Notes
    -----
    ``nextEntityId`` is initialized to one greater than the largest existing
    STEP id. The cache dictionaries are intentionally empty at creation and will
    be populated lazily by later stages of the IFC API refactor.
    """

    entities: Dict[int, IFCFastEntity]
    sourcePath: Optional[str] = None
    schema: Optional[str] = None
    header: Optional[str] = None
    modelId: str = field(default_factory=lambda: uuid.uuid4().hex)
    revision: int = 0
    dirty: bool = False
    metadataCache: Dict[Any, Any] = field(default_factory=dict, repr=False)
    placementCache: Dict[Any, Any] = field(default_factory=dict, repr=False)
    meshCache: Dict[Any, Any] = field(default_factory=dict, repr=False)
    topologyCache: Dict[Any, Any] = field(default_factory=dict, repr=False)
    propertyCache: Dict[Any, Any] = field(default_factory=dict, repr=False)
    tripleCache: Dict[Any, Any] = field(default_factory=dict, repr=False)
    summaryCache: Dict[Any, Any] = field(default_factory=dict, repr=False)
    indexes: Dict[str, Any] = field(default_factory=dict, repr=False)
    nextEntityId: int = field(init=False)

    def __post_init__(self):
        if not isinstance(self.entities, dict):
            raise TypeError("IFCModel.entities must be a dictionary.")

        if isinstance(self.sourcePath, str) and self.sourcePath.strip():
            self.sourcePath = os.path.abspath(self.sourcePath.strip())
        else:
            self.sourcePath = None

        if self.schema is not None:
            schema = str(self.schema).strip().upper()
            self.schema = schema or None

        if self.header is not None:
            header = str(self.header).strip()
            self.header = header or None

        self.modelId = str(self.modelId or uuid.uuid4().hex)
        self.revision = max(0, int(self.revision or 0))
        self.dirty = bool(self.dirty)
        self.nextEntityId = max(
            (key for key in self.entities if isinstance(key, int)),
            default=0,
        ) + 1

    def __contains__(self, entityId):
        return entityId in self.entities

    def __getitem__(self, entityId):
        return self.entities[entityId]

    def __len__(self):
        return len(self.entities)

    def __repr__(self):
        source = self.sourcePath or "<memory>"
        schema = self.schema or "UNKNOWN"
        return (
            f"<IFCModel schema={schema} entities={len(self.entities)} "
            f"revision={self.revision} source={source!r}>"
        )

    def get(self, entityId, default=None):
        """Returns the entity at the input STEP id."""
        return self.entities.get(entityId, default)

    def items(self):
        """Returns the model entity items view."""
        return self.entities.items()

    def keys(self):
        """Returns the model entity keys view."""
        return self.entities.keys()

    def values(self):
        """Returns the model entity values view."""
        return self.entities.values()

    def invalidateCaches(self, geometry: bool = False):
        """Invalidates cached data after an in-memory model modification."""
        self.metadataCache.clear()
        self.propertyCache.clear()
        self.tripleCache.clear()
        self.summaryCache.clear()
        self.indexes.clear()
        if geometry:
            self.placementCache.clear()
            self.meshCache.clear()
            self.topologyCache.clear()
        return self

    def touch(self, geometry: bool = False):
        """Marks the model as modified and invalidates affected caches."""
        self.revision += 1
        self.dirty = True
        self.nextEntityId = max(
            self.nextEntityId,
            max((key for key in self.entities if isinstance(key, int)), default=0) + 1,
        )
        self.invalidateCaches(geometry=geometry)
        return self

class IFCEntity:
    """
    Lightweight dynamic wrapper around an IFCFastEntity.

    This class exposes IFC root attributes, extracted properties,
    quantities, classifications, materials, and type information
    through Python attribute access.

    Example
    -------
    wall = IFC.Object(file, globalId)

    print(wall.GlobalId)
    print(wall.Name)
    print(wall.FireRating)
    print(wall.Materials)
    """

    _ROOT_ATTRS = {
        "GlobalId": 0,
        "OwnerHistory": 1,
        "Name": 2,
        "Description": 3,
    }

    def __init__(self, entity, entities=None, properties=None):
        self._entity = entity
        self._entities = entities or {}
        self._properties = properties or {}

    def __repr__(self):
        gid = self.GlobalId or ""
        return f"<{self.IFCType} #{self.IFCId} {gid}>"

    @property
    def IFCId(self):
        return self._entity.id if self._entity is not None else None

    @property
    def IFCKey(self):
        return f"#{self._entity.id}" if self._entity is not None else None

    @property
    def IFCType(self):
        if self._entity is None:
            return None

        t = self._entity.type

        if str(t).upper().startswith("IFC"):
            return "Ifc" + str(t)[3:].lower().title().replace("_", "")

        return t

    @property
    def Entity(self):
        """
        Returns the wrapped IFCFastEntity.
        """
        return self._entity

    @property
    def Properties(self):
        return self._properties.get("properties", {})

    @property
    def TypeProperties(self):
        return self._properties.get("type_properties", {})

    @property
    def Quantities(self):
        return self._properties.get("quantities", {})

    @property
    def TypeQuantities(self):
        return self._properties.get("type_quantities", {})

    @property
    def Classifications(self):
        return self._properties.get("classifications", [])

    @property
    def Materials(self):
        return self._properties.get("materials", [])

    @property
    def Type(self):
        return self._properties.get("type", None)

    def is_a(self, name=None):
        if self._entity is None:
            return None if name is None else False

        return self._entity.is_a(name)

    def Attribute(self, name, default=None):
        """
        Returns an attribute/property safely.
        """

        try:
            return getattr(self, name)
        except Exception:
            return default

    def ToDict(self):
        """
        Returns a serializable dictionary representation.
        """

        return {
            "ifc_id": self.IFCId,
            "ifc_key": self.IFCKey,
            "ifc_type": self.IFCType,
            "global_id": self.GlobalId,
            "name": self.Name,
            "description": self.Description,
            "properties": self.Properties,
            "type_properties": self.TypeProperties,
            "quantities": self.Quantities,
            "type_quantities": self.TypeQuantities,
            "classifications": self.Classifications,
            "materials": self.Materials,
            "type": self.Type,
        }

    def _normalise_name(self, value):
        if value is None:
            return ""

        return "".join(
            ch for ch in str(value).strip().lower()
            if ch.isalnum()
        )

    def _lookup_in_grouped_dict(self, grouped, name):
        """
        Searches grouped property dictionaries.

        Supports:
        - FireRating
        - Pset_WallCommon.FireRating
        """

        target = self._normalise_name(name)

        if not isinstance(grouped, dict):
            return None

        # Direct property search.
        for group_name, values in grouped.items():
            if not isinstance(values, dict):
                continue

            for key, value in values.items():
                if self._normalise_name(key) == target:
                    return value

        # Qualified search.
        if "." in str(name):
            group_part, key_part = str(name).split(".", 1)

            group_target = self._normalise_name(group_part)
            key_target = self._normalise_name(key_part)

            for group_name, values in grouped.items():
                if self._normalise_name(group_name) != group_target:
                    continue

                if not isinstance(values, dict):
                    continue

                for key, value in values.items():
                    if self._normalise_name(key) == key_target:
                        return value

        return None

    def __getattr__(self, name):
        """
        Dynamic IFC-style attribute lookup.

        Lookup order:
        1. IFC root attributes
        2. instance properties
        3. type properties
        4. instance quantities
        5. type quantities
        """

        # IFC root attributes.
        if name in IFCEntity._ROOT_ATTRS:
            index = IFCEntity._ROOT_ATTRS[name]

            try:
                return IFCFastTopology._root_attr(self._entity, index)
            except Exception:
                return None

        # Instance properties.
        value = self._lookup_in_grouped_dict(
            self.Properties,
            name
        )

        if value is not None:
            return value

        # Type properties.
        value = self._lookup_in_grouped_dict(
            self.TypeProperties,
            name
        )

        if value is not None:
            return value

        # Instance quantities.
        value = self._lookup_in_grouped_dict(
            self.Quantities,
            name
        )

        if value is not None:
            return value

        # Type quantities.
        value = self._lookup_in_grouped_dict(
            self.TypeQuantities,
            name
        )

        if value is not None:
            return value

        raise AttributeError(
            f"{self.IFCType} has no attribute '{name}'"
        )

class IFCFastTopology:
    """
    Experimental pure-Python IFC importer for TopologicPy topologies.

    Geometry parsing and mesh construction backend for the IFC public API.
    Legacy topology entry points delegate to IFC rather than duplicating it.

    Simple geometry uses direct mesh construction. Faces with holes and solid
    Booleans use the configured native kernel. Unsupported Boolean operands and
    advanced surfaces raise ValueError rather than returning misleading geometry.
    """

    _REC_HEAD_RE = re.compile(rb"^\s*#\s*(\d+)\s*=\s*([A-Z][A-Z0-9_]*)\s*\(", re.I)

    _PRODUCT_TYPES = {
        "IFCACTUATOR", "IFCAIRTERMINAL", "IFCAIRTERMINALBOX", "IFCAIRTOAIRHEATRECOVERY",
        "IFCALARM", "IFCANNOTATION", "IFCBEAM", "IFCBEAMSTANDARDCASE", "IFCBOILER",
        "IFCBUILDING", "IFCBUILDINGELEMENTPART", "IFCBUILDINGELEMENTPROXY", "IFCBUILDINGSTOREY",
        "IFCBURNER", "IFCCHILLER", "IFCCHIMNEY", "IFCCIVILELEMENT", "IFCCOLUMN",
        "IFCCOLUMNSTANDARDCASE", "IFCCOMPRESSOR", "IFCCONDENSER", "IFCCONTROLLER",
        "IFCCOOLEDBEAM", "IFCCOOLINGTOWER", "IFCCOVERING", "IFCCURTAINWALL", "IFCDAMPER",
        "IFCDISCRETEACCESSORY", "IFCDISTRIBUTIONCHAMBERELEMENT", "IFCDISTRIBUTIONCONTROLELEMENT",
        "IFCDISTRIBUTIONELEMENT", "IFCDISTRIBUTIONFLOWELEMENT", "IFCDOOR", "IFCDOORSTANDARDCASE",
        "IFCELECTRICAPPLIANCE", "IFCELECTRICDISTRIBUTIONBOARD", "IFCELECTRICFLOWSTORAGEDEVICE",
        "IFCELECTRICGENERATOR", "IFCELECTRICMOTOR", "IFCELECTRICTIMECONTROL", "IFCELEMENTASSEMBLY",
        "IFCENERGYCONVERSIONDEVICE", "IFCEVAPORATIVECOOLER", "IFCEVAPORATOR", "IFCFAN",
        "IFCFASTENER", "IFCFILTER", "IFCFIRESUPPRESSIONTERMINAL", "IFCFLOWCONTROLLER",
        "IFCFLOWFITTING", "IFCFLOWINSTRUMENT", "IFCFLOWMOVINGDEVICE", "IFCFLOWSEGMENT",
        "IFCFLOWSTORAGEDEVICE", "IFCFLOWTERMINAL", "IFCFLOWTREATMENTDEVICE", "IFCFOOTING",
        "IFCFURNISHINGELEMENT", "IFCFURNITURE", "IFCGEOGRAPHICELEMENT", "IFCGRID", "IFCGRIDAXIS",
        "IFCHEATEXCHANGER", "IFCHUMIDIFIER", "IFCINTERCEPTOR", "IFCJUNCTIONBOX", "IFCLAMP",
        "IFCLIGHTFIXTURE", "IFCMECHANICALFASTENER", "IFCMEMBER", "IFCMEMBERSTANDARDCASE",
        "IFCMOTORCONNECTION", "IFCOPENINGELEMENT", "IFCPILE", "IFCPIPEFITTING", "IFCPIPESEGMENT",
        "IFCPLATE", "IFCPLATESTANDARDCASE", "IFCPROJECT", "IFCPROJECTIONELEMENT", "IFCPROTECTIVEDEVICE",
        "IFCPROTECTIVEDEVICETRIPPINGUNIT", "IFCPUMP", "IFCRAILING", "IFCRAMP", "IFCRAMPFLIGHT",
        "IFCREINFORCINGBAR", "IFCREINFORCINGMESH", "IFCROOF", "IFCSANITARYTERMINAL", "IFCSHADINGDEVICE",
        "IFCSITE", "IFCSLAB", "IFCSLABELEMENTEDCASE", "IFCSLABSTANDARDCASE", "IFCSPACE",
        "IFCSPATIALELEMENT", "IFCSPATIALSTRUCTUREELEMENT", "IFCSTACKTERMINAL", "IFCSTAIR",
        "IFCSTAIRFLIGHT", "IFCSWITCHINGDEVICE", "IFCSYSTEMFURNITUREELEMENT", "IFCTANK",
        "IFCTRANSPORTELEMENT", "IFCTUBEBUNDLE", "IFCUNITARYCONTROLELEMENT", "IFCUNITARYEQUIPMENT",
        "IFCVALVE", "IFCVIRTUALELEMENT", "IFCWALL", "IFCWALLELEMENTEDCASE", "IFCWALLSTANDARDCASE",
        "IFCWASTETERMINAL", "IFCWINDOW", "IFCWINDOWSTANDARDCASE",
    }

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------


    @staticmethod
    def OpeningElementsByFillingType(
        entities: Dict[int, IFCFastEntity],
        fillingTypes: list = None,
        silent: bool = False,
    ) -> list:
        """
        Returns IfcOpeningElement entities that are filled by the requested IFC element types.

        Typical use:
            OpeningElementsByFillingType(entities, ["IfcDoor"])
            OpeningElementsByFillingType(entities, ["IfcWindow"])
        """

        if fillingTypes is None:
            fillingTypes = ["IfcDoor"]

        fillingTypes = {t.lower() for t in fillingTypes}
        openings = []
        seen = set()

        def _get_attr(entity, name, default=None):
            if entity is None:
                return default

            if hasattr(entity, name):
                return getattr(entity, name)

            attrs = getattr(entity, "attributes", None)
            if isinstance(attrs, dict):
                return attrs.get(name, default)

            data = getattr(entity, "data", None)
            if isinstance(data, dict):
                return data.get(name, default)

            if isinstance(entity, dict):
                return entity.get(name, default)

            return default

        def _ref_id(value):
            if value is None:
                return None

            if isinstance(value, int):
                return value

            if isinstance(value, str):
                value = value.strip()
                if value.startswith("#"):
                    value = value[1:]
                if value.isdigit():
                    return int(value)
                return None

            entity_id = getattr(value, "id", None)
            if isinstance(entity_id, int):
                return entity_id

            if callable(entity_id):
                try:
                    return entity_id()
                except Exception:
                    return None

            return None

        for rel in entities.values():
            rel_type = getattr(rel, "type", None)
            if not isinstance(rel_type, str):
                continue

            if rel_type.lower() != "ifcrelfillselement":
                continue

            opening_ref = _get_attr(rel, "RelatingOpeningElement")
            filling_ref = _get_attr(rel, "RelatedBuildingElement")

            opening_id = _ref_id(opening_ref)
            filling_id = _ref_id(filling_ref)

            if opening_id is None or filling_id is None:
                continue

            opening = entities.get(opening_id)
            filling = entities.get(filling_id)

            if opening is None or filling is None:
                continue

            opening_type = getattr(opening, "type", "").lower()
            filling_type = getattr(filling, "type", "").lower()

            if opening_type != "ifcopeningelement":
                continue

            if filling_type not in fillingTypes:
                continue

            if opening_id not in seen:
                openings.append(opening)
                seen.add(opening_id)

        if not openings and not silent:
            print(
                "IFCFastTopology.OpeningElementsByFillingType - Warning: "
                "No matching IfcOpeningElement entities were found. "
                "The IFC file may not contain IfcRelFillsElement relationships."
            )

        return openings
    
    @staticmethod
    def TopologiesByPath(path: str,
                         includeTypes: list = [],
                         excludeTypes: list = [],
                         dictionaryMode: str = "basic",
                         clean: bool = False,
                         scale: Optional[float] = None,
                         topologyType: str = None,
                         circleSides: int = 24,
                         ontology: bool = True,
                         epsilon: float = 0.01,
                         angTolerance: float = 0.1,
                         tolerance: float = 0.0001,
                         silent: bool = False) -> list:
        """
        Imports IFC product geometry from a file path into TopologicPy topologies.

        Parameters
        ----------
        path : str
            The path to the input IFC file.
        includeTypes : list , optional
            The list of IFC entity types to include. If empty, all supported types are
            included. Default is [].
        excludeTypes : list , optional
            The list of IFC entity types to exclude. Default is [].
        dictionaryMode : str , optional
            The dictionary import mode. Options are "none", "basic", and "full".
            Default is "basic".
        clean : bool , optional
            If set to True, the imported topologies are cleaned. Default is False.
        scale : float , optional
            Deprecated raw-coordinate multiplier. Default is None, which converts
            IFC length units to metres. An explicit finite, positive value
            overrides automatic unit conversion and keeps legacy behavior.
        topologyType : str , optional
            The desired output topology type. If set to None, the method returns the
            most appropriate topology type for each imported product. Default is None.
        circleSides : int , optional
            The number of sides used to approximate circular geometry. Default is 24.
        ontology : bool , optional
            If set to True, ontology metadata and semantic class annotations are added
            to the imported topologies. Default is True.
        epsilon : float , optional
            The geometric epsilon used during import. Default is 0.01.
        angTolerance : float , optional
            The angular tolerance used during import. Default is 0.1.
        tolerance : float , optional
            The desired tolerance. Default is 0.0001.
        silent : bool , optional
            If set to True, error and warning messages are suppressed. Default is False.

        Returns
        -------
        list
            The list of imported TopologicPy topologies.

        """
        return IFC.TopologiesByPath(
            path,
            includeTypes=includeTypes,
            excludeTypes=excludeTypes,
            dictionaryMode=dictionaryMode,
            clean=clean,
            scale=scale,
            topologyType=topologyType,
            circleSides=circleSides,
            ontology=ontology,
            epsilon=epsilon,
            angTolerance=angTolerance,
            tolerance=tolerance,
            silent=silent,
        )

    @staticmethod
    def TopologiesByFile(file,
                         includeTypes: list = [],
                         excludeTypes: list = [],
                         dictionaryMode: str = "basic",
                         clean: bool = False,
                         scale: Optional[float] = None,
                         topologyType: str = None,
                         circleSides: int = 24,
                         ontology: bool = True,
                         epsilon: float = 0.01,
                         angTolerance: float = 0.1,
                         tolerance: float = 0.0001,
                         silent: bool = False) -> list:


        """
        Imports IFC product geometry from a file path into TopologicPy topologies.

        Parameters
        ----------
        file : str or ifcopenshell.file-like object
            Prefer passing a path string. If an ifcopenshell file-like object is
            supplied, this method attempts to serialise it to STEP text.
        includeTypes : list , optional
            The list of IFC entity types to include. If empty, all supported types are
            included. Default is [].
        excludeTypes : list , optional
            The list of IFC entity types to exclude. Default is [].
        dictionaryMode : str , optional
            The dictionary import mode. Options are "none", "basic", and "full".
            Default is "basic".
        clean : bool , optional
            If set to True, the imported topologies are cleaned. Default is False.
        scale : float , optional
            Deprecated raw-coordinate multiplier. Default is None, which converts
            IFC length units to metres. An explicit finite, positive value
            overrides automatic unit conversion and keeps legacy behavior.
        topologyType : str , optional
            The desired output topology type. If set to None, the method returns the
            most appropriate topology type for each imported product. Default is None.
        circleSides : int , optional
            The number of sides used to approximate circular geometry. Default is 24.
        ontology : bool , optional
            If set to True, ontology metadata and semantic class annotations are added
            to the imported topologies. Default is True.
        epsilon : float , optional
            The geometric epsilon used during import. Default is 0.01.
        angTolerance : float , optional
            The angular tolerance used during import. Default is 0.1.
        tolerance : float , optional
            The desired tolerance. Default is 0.0001.
        silent : bool , optional
            If set to True, error and warning messages are suppressed. Default is False.

        Returns
        -------
        list
            The list of imported TopologicPy topologies.

        """
        return IFC.TopologiesByFile(
            file,
            includeTypes=includeTypes,
            excludeTypes=excludeTypes,
            dictionaryMode=dictionaryMode,
            clean=clean,
            scale=scale,
            topologyType=topologyType,
            circleSides=circleSides,
            ontology=ontology,
            epsilon=epsilon,
            angTolerance=angTolerance,
            tolerance=tolerance,
            silent=silent,
        )

    @staticmethod
    def MeshDataByPath(path: str,
                       includeTypes: list = [],
                       excludeTypes: list = [],
                       dictionaryMode: str = "basic",
                       circleSides: int = 24,
                       scale: Optional[float] = None,
                       ontology: bool = True,
                       silent: bool = False) -> dict:
        """Compatibility wrapper for IFC.MeshDataByPath."""
        return IFC.MeshDataByPath(
            path,
            includeTypes=includeTypes,
            excludeTypes=excludeTypes,
            dictionaryMode=dictionaryMode,
            circleSides=circleSides,
            scale=scale,
            ontology=ontology,
            silent=silent,
        )

    @staticmethod
    def TopologiesByEntities(entities: Dict[int, IFCFastEntity],
                             includeTypes: list = [],
                             excludeTypes: list = [],
                             dictionaryMode: str = "basic",
                             clean: bool = False,
                             epsilon: float = 0.01,
                             angTolerance: float = 0.1,
                             tolerance: float = 0.0001,
                             circleSides: int = 24,
                             topologyType: str = None,
                             scale: Optional[float] = None,
                             ontology: bool = True,
                             source: str = None,
                             silent: bool = False) -> list:
        
        """Compatibility wrapper; IFC.Topologies owns topology construction."""
        return IFC.TopologiesByEntities(
            entities,
            includeTypes=includeTypes,
            excludeTypes=excludeTypes,
            dictionaryMode=dictionaryMode,
            clean=clean,
            scale=scale,
            topologyType=topologyType,
            circleSides=circleSides,
            ontology=ontology,
            epsilon=epsilon,
            angTolerance=angTolerance,
            tolerance=tolerance,
            silent=silent,
            source=source,
        )

    @staticmethod
    def SummaryByPath(path: str, silent: bool = False) -> dict:
        """Returns the legacy summary fields through the canonical IFC API."""
        summary = IFC.SummaryByPath(path, silent=silent)
        if summary is None:
            return None
        return {key: summary[key] for key in (
            "entity_count", "product_count", "entity_type_counts",
            "product_type_counts", "shape_representation_counts",
            "representation_item_counts",
        )}

    # ------------------------------------------------------------------
    # STEP parsing
    # ------------------------------------------------------------------

    @staticmethod
    def Parse(path: str, silent: bool = False) -> Dict[int, IFCFastEntity]:
        with open(path, "rb") as f:
            data = f.read()
        entities = IFCFastTopology.ParseBytes(data, silent=True)
        return entities

    @staticmethod
    def ParseText(text: str, silent: bool = False) -> Dict[int, IFCFastEntity]:
        data = text.encode("utf-8", errors="ignore")
        return IFCFastTopology.ParseBytes(data, silent=silent)

    @staticmethod
    def ParseBytes(data: bytes, silent: bool = False) -> Dict[int, IFCFastEntity]:
        entities: Dict[int, IFCFastEntity] = {}
        start = time.time()
        for stmt in IFCFastTopology._iter_step_statements(data):
            m = IFCFastTopology._REC_HEAD_RE.match(stmt)
            if not m:
                continue
            step_id = int(m.group(1))
            entity_type = m.group(2).decode("ascii", errors="ignore").upper()
            p0 = stmt.find(b"(", m.end() - 1)
            p1 = stmt.rfind(b")")
            if p0 < 0 or p1 <= p0:
                continue
            raw_args = stmt[p0 + 1:p1].decode("utf-8", errors="ignore")
            try:
                args = _STEPArgParser(raw_args).parse_list_content()
                entities[step_id] = IFCFastEntity(step_id, entity_type, args)
            except Exception as e:
                if not silent:
                    print(f"IFCFastTopology.ParseBytes - Warning: Could not parse #{step_id}={entity_type}: {e}")
        if not silent:
            print(f"IFCFastTopology.ParseBytes - Parsed {len(entities)} entities in {time.time() - start:.3f}s.")
        return entities

    @staticmethod
    def _iter_step_statements(data: bytes) -> Iterator[bytes]:
        """
        Fast IFC STEP statement splitter.

        IFC exchange files are statement-oriented and each entity assignment ends
        with a semicolon. This intentionally uses a direct byte split for speed.
        It is substantially faster and avoids pathological behaviour caused by
        malformed or non-standard apostrophe escaping in large STEP strings.
        Semicolons inside string literals are theoretically possible but rare in
        authoring-tool IFC exports; if encountered, only that individual record
        is likely to fail parsing and will be skipped.
        """
        for stmt in data.split(b";"):
            stmt = stmt.strip()
            if stmt.startswith(b"#") or stmt.startswith(b"\r#") or stmt.startswith(b"\n#"):
                yield stmt

    @staticmethod
    def _file_to_step_text(file: Any) -> Optional[str]:
        if file is None:
            return None
        # IfcOpenShell usually supports to_string() on the file object.
        for attr in ("to_string",):
            fn = getattr(file, attr, None)
            if callable(fn):
                try:
                    s = fn()
                    if isinstance(s, bytes):
                        return s.decode("utf-8", errors="ignore")
                    if isinstance(s, str) and "ISO-10303-21" in s:
                        return s
                except Exception:
                    pass
        try:
            s = str(file)
            if "ISO-10303-21" in s:
                return s
        except Exception:
            pass
        return None

    # ------------------------------------------------------------------
    # Product selection / mesh extraction
    # ------------------------------------------------------------------

    @staticmethod
    def ProductsByEntities(entities: Dict[int, IFCFastEntity], includeTypes: list = [], excludeTypes: list = []) -> list:
        include = IFCFastTopology._normalise_type_set(includeTypes)
        exclude = IFCFastTopology._normalise_type_set(excludeTypes)
        products = []
        feature_subtraction_types = {"IFCOPENINGELEMENT", "IFCFEATUREELEMENTSUBTRACTION", "IFCVOIDINGFEATURE"}
        for e in entities.values():
            if include and e.type not in include:
                continue
            if exclude and e.type in exclude:
                continue
            # Match IFC.TopologiesByFile/IfcOpenShell behaviour more closely: do not
            # import subtraction features such as IfcOpeningElement as standalone
            # visible products unless the caller explicitly requests them.
            if not include and e.type in feature_subtraction_types:
                continue
            if IFCFastTopology._is_product_like(e):
                products.append(e)
        products.sort(key=lambda ent: ent.id)
        return products

    @staticmethod
    def MeshDataByProducts(products: list,
                           entities: Dict[int, IFCFastEntity],
                           dictionaryMode: str = "basic",
                           circleSides: int = 24,
                           scale: Optional[float] = None,
                           ontology: bool = True,
                           source: str = None,
                           silent: bool = False) -> dict:
        scale = IFCFastTopology._coordinate_scale(entities, scale)
        vertices, edges, faces, vertex_dictionaries, product_ranges = [], [], [], [], []
        metadata_cache = IFCFastTopology._entity_metadata_cache(entities, dictionaryMode=dictionaryMode)
        placement_cache = {}
        for product in products:
            mesh = IFCFastTopology.MeshDataByProduct(product, entities, circleSides=circleSides, scale=scale, placementCache=placement_cache)
            if not mesh or not mesh.get("vertices"):
                continue
            d = IFCFastTopology._entity_dictionary(product, dictionaryMode, metadataCache=metadata_cache, ontology=ontology, source=source, generatedBy='IFCFastTopology.MeshDataByProducts')
            v0, e0, f0 = len(vertices), len(edges), len(faces)
            vertices.extend(mesh.get("vertices") or [])
            vertex_dictionaries.extend([d] * len(mesh.get("vertices") or []))
            edges.extend([[a + v0, b + v0] for a, b in (mesh.get("edges") or [])])
            faces.extend([[i + v0 for i in face] for face in (mesh.get("faces") or [])])
            product_ranges.append({
                "id": product.id,
                "type": product.type,
                "global_id": IFCFastTopology._root_attr(product, 0),
                "name": IFCFastTopology._root_attr(product, 2),
                "start": v0,
                "end": len(vertices),
                "edge_start": e0,
                "edge_end": len(edges),
                "face_start": f0,
                "face_end": len(faces),
            })
        if not silent:
            print(
                f"IFCFastTopology.MeshDataByProducts - Extracted {len(product_ranges)} products, "
                f"{len(vertices)} vertices, {len(edges)} edges, {len(faces)} faces."
            )
        return {"vertices": vertices, "edges": edges, "faces": faces, "vertex_dictionaries": vertex_dictionaries, "product_ranges": product_ranges}

    @staticmethod
    def _validated_scale(scale):
        """Rejects degenerate or non-finite coordinate multipliers."""
        if isinstance(scale, bool) or not isinstance(scale, Real):
            raise ValueError("scale must be a finite, positive number")
        try:
            scale = float(scale)
        except (ValueError, TypeError, OverflowError) as error:
            raise ValueError("scale must be a finite, positive number") from error
        if not math.isfinite(scale) or scale <= 0:
            raise ValueError("scale must be a finite, positive number")
        return scale

    @staticmethod
    def _length_unit_scale(entities):
        """Resolves project length units to metres without changing STEP data.

        Unitless fragments retain the historical assumption of metres. Declared
        but invalid, unsupported, or conflicting length units raise ValueError.
        Only project-assigned units are considered, so property-specific units
        cannot accidentally determine the geometry unit.
        """
        prefixes = {
            None: 1.0, "EXA": 1e18, "PETA": 1e15, "TERA": 1e12,
            "GIGA": 1e9, "MEGA": 1e6, "KILO": 1e3, "HECTO": 1e2,
            "DECA": 1e1, "DECI": 1e-1, "CENTI": 1e-2, "MILLI": 1e-3,
            "MICRO": 1e-6, "NANO": 1e-9, "PICO": 1e-12,
            "FEMTO": 1e-15, "ATTO": 1e-18,
        }

        def entity_at(reference):
            entity = IFCFastTopology._entity_from_ref(reference, entities)
            if entity is None:
                raise ValueError("IFC length unit contains an unresolved reference")
            return entity

        def argument(entity, index):
            return entity.args[index] if len(entity.args) > index else None

        def unit_factor(unit, visited):
            if unit.id in visited:
                raise ValueError("IFC length unit conversion contains a cycle")
            visited = visited | {unit.id}
            if argument(unit, 1) != "LENGTHUNIT":
                raise ValueError("IFC length conversion must reference a length unit")
            if unit.type == "IFCSIUNIT":
                prefix = argument(unit, 2)
                if argument(unit, 3) != "METRE" or prefix not in prefixes:
                    raise ValueError("Unsupported IFC SI length unit")
                return prefixes[prefix]
            if unit.type in ("IFCCONVERSIONBASEDUNIT", "IFCCONVERSIONBASEDUNITWITHOFFSET"):
                if unit.type.endswith("WITHOFFSET") and argument(unit, 4) != 0:
                    raise ValueError("IFC length units with nonzero offsets are unsupported")
                measure = entity_at(argument(unit, 3))
                if measure.type != "IFCMEASUREWITHUNIT":
                    raise ValueError("Invalid IFC length conversion factor")
                value = argument(measure, 0)
                if isinstance(value, tuple) and len(value) == 3 and value[0] == "CALL":
                    values = value[2]
                    if len(values) != 1:
                        raise ValueError("Invalid IFC length conversion value")
                    value = values[0]
                factor = IFCFastTopology._validated_scale(value)
                base = entity_at(argument(measure, 1))
                return IFCFastTopology._validated_scale(factor * unit_factor(base, visited))
            raise ValueError("Unsupported IFC length unit: " + unit.type)

        projects = [e for e in entities.values() if e.type == "IFCPROJECT"]
        assignments = []
        for project in projects:
            reference = argument(project, 8)
            if reference is None:
                continue
            assignment = entity_at(reference)
            if assignment.type != "IFCUNITASSIGNMENT":
                raise ValueError("Invalid IFC project unit assignment")
            assignments.append(assignment)
        if not projects:
            assignments = [e for e in entities.values() if e.type == "IFCUNITASSIGNMENT"]
        if not assignments:
            return 1.0

        factors = []
        for assignment in assignments:
            units = [entity_at(ref) for ref in IFCFastTopology._refs_in_value(argument(assignment, 0))]
            lengths = [unit for unit in units if argument(unit, 1) == "LENGTHUNIT"]
            if len(lengths) != 1:
                raise ValueError("IFC unit assignment must contain exactly one length unit")
            factors.append(unit_factor(lengths[0], set()))
        if any(not math.isclose(factor, factors[0], rel_tol=1e-12, abs_tol=0.0) for factor in factors[1:]):
            raise ValueError("IFC projects declare conflicting length units")
        return factors[0]

    @staticmethod
    def _coordinate_scale(entities, scale=None):
        """None uses IFC units; explicit scale retains legacy raw multiplication."""
        if scale is not None:
            return IFCFastTopology._validated_scale(scale)
        return IFCFastTopology._length_unit_scale(entities)

    @staticmethod
    def MeshDataByProduct(product: IFCFastEntity,
                          entities: Dict[int, IFCFastEntity],
                          circleSides: int = 24,
                          scale: Optional[float] = None,
                          placementCache: dict = None) -> Optional[dict]:
        scale = IFCFastTopology._coordinate_scale(entities, scale)
        placement = IFCFastTopology._product_placement_matrix(
            product,
            entities,
            cache=placementCache,
        )
        rep_ref = product.args[6] if len(product.args) > 6 else None
        rep = IFCFastTopology._entity_from_ref(rep_ref, entities)
        if rep is None or rep.type != "IFCPRODUCTDEFINITIONSHAPE":
            return None

        # IFC products often carry several shape representations simultaneously,
        # for example Body + Axis + BoundingBox. IFC.TopologiesByFile/IfcOpenShell
        # effectively imports the visible/body geometry. Merging every
        # representation into one TopologicPy object creates apparent placement
        # errors: walls get their axis curves, windows get their bounding boxes,
        # and panes may appear duplicated or offset.
        shape_reps = []
        for sr_ref in IFCFastTopology._refs_in_value(rep.args[2] if len(rep.args) > 2 else None):
            sr = IFCFastTopology._entity_from_ref(sr_ref, entities)
            if sr is None or sr.type != "IFCSHAPEREPRESENTATION":
                continue
            identifier = str(sr.args[1]).upper() if len(sr.args) > 1 and sr.args[1] not in (None, "*") else ""
            rep_type = str(sr.args[2]).upper() if len(sr.args) > 2 and sr.args[2] not in (None, "*") else ""
            shape_reps.append((identifier, rep_type, sr))

        if not shape_reps:
            return None

        body_reps = [sr for ident, rtype, sr in shape_reps if ident == "BODY"]
        if body_reps:
            selected_reps = body_reps
        else:
            non_bbox = [(ident, rtype, sr) for ident, rtype, sr in shape_reps if rtype != "BOUNDINGBOX" and ident != "BOX"]
            # Prefer footprint/curve geometry for virtual elements and other
            # products that genuinely have no Body representation. Avoid Axis
            # unless it is the only available representation.
            non_axis = [sr for ident, rtype, sr in non_bbox if ident != "AXIS"]
            selected_reps = non_axis if non_axis else [sr for ident, rtype, sr in non_bbox]
            if not selected_reps:
                # Last resort: explicit IFC bounding box. This is useful for very
                # coarse models, but it must not be merged with body geometry.
                selected_reps = [sr for ident, rtype, sr in shape_reps if rtype == "BOUNDINGBOX" or ident == "BOX"]

        meshes = []
        for sr in selected_reps:
            for item_ref in IFCFastTopology._refs_in_value(sr.args[3] if len(sr.args) > 3 else None):
                item = IFCFastTopology._entity_from_ref(item_ref, entities)
                if item is None:
                    continue
                m = IFCFastTopology._mesh_from_item(item, entities, placement, circleSides=circleSides, scale=scale)
                if m is not None and m.get("vertices"):
                    meshes.append(m)
        if not meshes:
            return None
        mesh = IFCFastTopology._merge_meshes(meshes, dedupe=True)
        index_key = ("voids", id(entities), len(entities))
        opening_index = placementCache.get(index_key) if isinstance(placementCache, dict) else None
        if opening_index is None:
            opening_index = {}
            for relation in entities.values():
                if relation.type == "IFCRELVOIDSELEMENT" and len(relation.args) >= 6:
                    host = IFCFastTopology._entity_from_ref(relation.args[4], entities)
                    if host is not None:
                        opening_index.setdefault(host.id, []).append(relation.args[5])
            if isinstance(placementCache, dict):
                placementCache[index_key] = opening_index
        active_key = ("active_openings", id(entities))
        cache = placementCache if isinstance(placementCache, dict) else {}
        active = cache.setdefault(active_key, set())
        if product.id in active:
            raise ValueError("Cyclic IFC opening relationships")
        for opening_ref in opening_index.get(product.id, []):
            opening = IFCFastTopology._entity_from_ref(opening_ref, entities)
            if opening is None:
                raise ValueError("Missing IFC opening element")
            active.add(product.id)
            try:
                cutter = IFCFastTopology.MeshDataByProduct(opening, entities, circleSides, scale, cache)
                mesh = IFCFastTopology._boolean_mesh(mesh, cutter, "DIFFERENCE")
            finally:
                active.remove(product.id)
        return mesh

    @staticmethod
    def _closed_polygon_mesh(polygons):
        """Index a conforming closed polygon shell, or reject the fast path."""
        from collections import Counter
        from itertools import product
        import math
        vertices, faces, lookup = [], [], {}
        tolerance = 1e-7
        for polygon in polygons:
            ids = []
            for point in polygon:
                key = tuple(math.floor(float(v)/tolerance) for v in point)
                index = None
                for offset in product((-1, 0, 1), repeat=3):
                    neighbour = tuple(k+d for k, d in zip(key, offset))
                    for candidate in lookup.get(neighbour, []):
                        if sum((float(v)-w)**2 for v, w in zip(point, vertices[candidate])) <= tolerance**2:
                            index = candidate
                            break
                    if index is not None:
                        break
                if index is None:
                    index = len(vertices)
                    lookup.setdefault(key, []).append(index)
                    vertices.append([float(v) for v in point])
                if not ids or ids[-1] != index:
                    ids.append(index)
            if len(ids) > 1 and ids[0] == ids[-1]:
                ids.pop()
            if len(ids) >= 3:
                # Triangulation can create collinear cap triangles at a cut
                # touching a floor within floating-point precision. They are
                # not surfaces; retain their vertices for edge noding below.
                origin = vertices[ids[0]]
                deltas = [[p[k]-origin[k] for k in range(3)] for p in (vertices[i] for i in ids)]
                axis = max(deltas, key=lambda d: sum(v*v for v in d))
                length2 = sum(v*v for v in axis)
                if all(sum((d[(k+1)%3]*axis[(k+2)%3]-d[(k+2)%3]*axis[(k+1)%3])**2 for k in range(3)) <= tolerance**2*length2 for d in deltas):
                    continue
                faces.append(ids)
        if not faces:
            return {"vertices": [], "faces": [], "edges": []}
        counts = Counter(tuple(sorted((a, b))) for f in faces for a, b in zip(f, f[1:]+f[:1]))
        if any(count != 2 for count in counts.values()):
            # Noding T-junctions changes no surface: neighbouring wall panels
            # can introduce intermediate heights along an existing edge.
            import numpy as np
            points = np.array(vertices)
            splits = {}
            for a, b in counts:
                delta = points[b]-points[a]
                length2 = delta@delta
                if length2 < 1e-20:
                    return None
                t = (points-points[a])@delta/length2
                residual = points-(points[a]+t[:, None]*delta)
                ids = np.flatnonzero((t > 1e-9) & (t < 1-1e-9) & (np.linalg.norm(residual, axis=1) < 2e-8))
                splits[a, b] = [int(i) for i in ids[np.argsort(t[ids])]]
            conformed = []
            for f in faces:
                ring = []
                for a, b in zip(f, f[1:]+f[:1]):
                    ring.append(a)
                    ring.extend(splits[a, b] if a < b else reversed(splits[b, a]))
                conformed.append(ring)
            faces = conformed
            counts = Counter(tuple(sorted((a, b))) for f in faces for a, b in zip(f, f[1:]+f[:1]))
        if any(count != 2 for count in counts.values()):
            return None
        # Compound shells and enclosed cavities retain the general kernel path.
        incidence = {}
        adjacent = [set() for _ in faces]
        for index, f in enumerate(faces):
            for a, b in zip(f, f[1:]+f[:1]):
                key = tuple(sorted((a, b)))
                if key in incidence:
                    other = incidence[key]
                    adjacent[index].add(other)
                    adjacent[other].add(index)
                else:
                    incidence[key] = index
        visited, pending = set(), [0]
        while pending:
            index = pending.pop()
            if index not in visited:
                visited.add(index)
                pending.extend(adjacent[index]-visited)
        if len(visited) != len(faces):
            return None
        return {"vertices": vertices, "faces": faces, "edges": []}

    @staticmethod
    def _prism_profile(mesh, axis=None):
        """Recognise a straight prism from equal caps and straight side faces."""
        import numpy as np
        from shapely.geometry import Polygon
        from shapely.ops import unary_union
        points = np.asarray(mesh.get("vertices", []), dtype=float)
        if len(points) < 4 or not mesh.get("faces"):
            return None
        mesh = IFCFastTopology._closed_polygon_mesh([points[f] for f in mesh["faces"]])
        if mesh is None or not mesh["faces"]:
            return None
        points = np.asarray(mesh["vertices"], dtype=float)
        tolerance = max(1e-7, float(np.ptp(points, axis=0).max())*1e-10)
        normals = {}
        if axis is not None:
            normal = np.asarray(axis, dtype=float)
            normals[tuple(normal)] = normal
        else:
            for ids in mesh["faces"]:
                p = points[ids]
                n = np.cross(p, np.roll(p, -1, axis=0)).sum(axis=0)
                length = np.linalg.norm(n)
                if length < 1e-10:
                    continue
                n /= length
                if next(v for v in n if abs(v) > 1e-10) < 0:
                    n = -n
                normals[tuple(np.round(n, 8))] = n
        for n in sorted(normals.values(), key=lambda n: float(np.ptp(points@n))):
            depths = points@n
            low, high = float(depths.min()), float(depths.max())
            if high-low < tolerance or np.any(np.minimum(abs(depths-low), abs(depths-high)) > tolerance):
                continue
            u = np.cross(n, np.eye(3)[int(np.argmin(abs(n)))])
            u /= np.linalg.norm(u)
            v = np.cross(n, u)
            projected = np.column_stack((points@u, points@v))
            caps = [[], []]
            supported = True
            for ids in mesh["faces"]:
                d = depths[ids]
                poly = Polygon(projected[ids])
                if max(abs(d-low)) <= tolerance or max(abs(d-high)) <= tolerance:
                    if not poly.is_valid or poly.area <= tolerance**2:
                        supported = False
                        break
                    caps[int(max(abs(d-high)) <= tolerance)].append(poly)
                elif poly.area > tolerance*max(1., np.ptp(projected[ids], axis=0).max()):
                    supported = False  # A warped/non-prismatic side must use CSG.
                    break
            if not supported or not all(caps):
                continue
            first, second = (unary_union(c) for c in caps)
            if first.symmetric_difference(second).area > max(1e-8, first.area*1e-8):
                continue
            return n, u, v, low, high, first
        return None

    @staticmethod
    def _prismatic_difference(a, b):
        """Exact through-cut in a common prism frame; None means use 3D CSG.

        Partial-depth pockets, differing caps and incomplete triangulations are
        deliberately not approximated. No source opening is omitted.
        """
        import numpy as np
        from collections import Counter
        from shapely.ops import triangulate
        host = IFCFastTopology._prism_profile(a)
        if host is None:
            return None
        n, u, v, low, high, profile = host
        cutter = IFCFastTopology._prism_profile(b, n)
        if cutter is None or cutter[3] > low+1e-7 or cutter[4] < high-1e-7:
            return None
        result = profile.difference(cutter[5])
        if result.is_empty:
            return {"vertices": [], "faces": [], "edges": []}
        if not result.is_valid or result.geom_type not in {"Polygon", "MultiPolygon"}:
            return None
        if result.equals(profile):
            return a
        polygons = [result] if result.geom_type == "Polygon" else list(result.geoms)
        faces = []
        for polygon in polygons:
            triangles = [t for t in triangulate(polygon) if polygon.covers(t)]
            if abs(sum(t.area for t in triangles)-polygon.area) > max(1e-8, polygon.area*1e-8):
                return None
            counts, directions = Counter(), {}
            def point(p, depth):
                return u*p[0]+v*p[1]+n*depth
            for triangle in triangles:
                p = list(triangle.exterior.coords)[:-1]
                if not triangle.exterior.is_ccw:
                    p.reverse()
                faces.append([point(q, low) for q in reversed(p)])
                faces.append([point(q, high) for q in p])
                for start, end in zip(p, p[1:]+p[:1]):
                    key = tuple(sorted((tuple(start), tuple(end))))
                    counts[key] += 1
                    directions[key] = (start, end)
            for key, count in counts.items():
                if count == 1:
                    start, end = directions[key]
                    faces.append([point(start, low), point(end, low), point(end, high), point(start, high)])
        return IFCFastTopology._closed_polygon_mesh(faces)

    @staticmethod
    def _column_difference(a, b):
        """Exact polyhedral cuts in a conforming vertical-column arrangement.

        Plane projections are subdivided at every crossing before interval
        subtraction. This preserves mitered wall ends, roof steps, full-depth
        openings and partial-depth pockets, without solid Boolean operations.
        Complex/nonconforming inputs fall back to the general geometry kernel.
        """
        import numpy as np
        from collections import defaultdict
        from shapely import union_all
        from shapely.geometry import Polygon, LineString
        from shapely.ops import unary_union, polygonize, triangulate
        from shapely.strtree import STRtree
        if len(a.get("faces", []))+len(b.get("faces", [])) > 2000:
            return None
        pa, pb = np.asarray(a["vertices"], dtype=float), np.asarray(b["vertices"], dtype=float)
        if np.any(pa.max(0) <= pb.min(0)+1e-8) or np.any(pb.max(0) <= pa.min(0)+1e-8):
            return a
        def surfaces(mesh):
            points = np.array(mesh["vertices"], dtype=float)
            if IFCFastTopology._closed_polygon_mesh([points[f] for f in mesh["faces"]]) is None:
                return None
            grouped = defaultdict(list)
            for ids in mesh["faces"]:
                p = points[ids]
                shifted = p-p[0]
                n = np.cross(shifted, np.roll(shifted, -1, axis=0)).sum(0)
                length = np.linalg.norm(n)
                if length < 1e-12:
                    return None
                n /= length
                if max(abs(shifted@n)) > 1e-7:
                    return None
                if abs(n[2]) < 1e-10:
                    continue
                poly = Polygon(p[:, :2])
                if not poly.is_valid or poly.area < 1e-12:
                    return None
                coefficient = (-n[0]/n[2], -n[1]/n[2], float(n@p[0]/n[2]))
                grouped[tuple(round(v, 10) for v in coefficient)].append(poly)
            if len(grouped) > 64:
                return None
            return [(np.array(c), unary_union(p)) for c, p in grouped.items()]
        sa, sb = surfaces(a), surfaces(b)
        if not sa or not sb:
            return None
        all_surfaces = sa+sb
        polys = [p for _, p in all_surfaces]
        tree = STRtree(polys)
        lines = [p.boundary for p in polys]
        for i, (coefficient, poly) in enumerate(all_surfaces):
            for j in tree.query(poly):
                j = int(j)
                if j <= i:
                    continue
                delta = coefficient-all_surfaces[j][0]
                length = np.linalg.norm(delta[:2])
                if length < 1e-10:
                    continue
                overlap = poly.intersection(polys[j])
                if overlap.area < 1e-12:
                    continue
                c = np.array(overlap.representative_point().coords[0])
                c -= delta[:2]*(delta[:2]@c+delta[2])/length**2
                d = np.array([-delta[1], delta[0]])/length
                extent = max(overlap.bounds[2]-overlap.bounds[0], overlap.bounds[3]-overlap.bounds[1])*2+1
                cut = LineString([c-d*extent, c+d*extent]).intersection(overlap)
                if cut.length > 1e-8:
                    lines.append(cut)
        atoms = list(polygonize(union_all(lines, grid_size=1e-8)))
        if len(atoms) > 2048:
            return None
        intervals, changed = [], False
        def z(c, p):
            return float(c@[p[0], p[1], 1.])
        def ordered(items, point):
            result = []
            for c in sorted(items, key=lambda c: z(c, point)):
                if not result or z(c, point)-z(result[-1], point) > 1e-7:
                    result.append(c)
            return result
        for atom in atoms:
            p = np.array(atom.representative_point().coords[0])
            inside = [[c for c, poly in surfaces if poly.covers(atom.representative_point())] for surfaces in (sa, sb)]
            aa, bb = (ordered(c, p) for c in inside)
            if len(aa) % 2 or len(bb) % 2:
                return None
            bounds = ordered(aa+bb, p)
            spans = []
            for low, high in zip(bounds, bounds[1:]):
                mid = .5*(z(low, p)+z(high, p))
                in_a = any(z(aa[i], p) < mid < z(aa[i+1], p) for i in range(0, len(aa), 2))
                in_b = any(z(bb[i], p) < mid < z(bb[i+1], p) for i in range(0, len(bb), 2))
                changed |= in_a and in_b
                if in_a and not in_b:
                    spans.append((low, high))
            intervals.append(spans)
        if not changed:
            return a
        faces, edges = [], defaultdict(list)
        for j, (atom, spans) in enumerate(zip(atoms, intervals)):
            if not spans:
                continue
            caps = [atom]
            if atom.interiors:
                caps = [t for t in triangulate(atom) if atom.covers(t)]
                if abs(sum(p.area for p in caps)-atom.area) > max(1e-8, atom.area*1e-8):
                    return None
            for low, high in spans:
                for poly in caps:
                    p = list(poly.exterior.coords)[:-1]
                    if not poly.exterior.is_ccw:
                        p.reverse()
                    faces.append([[x, y, z(low, (x, y))] for x, y in reversed(p)])
                    faces.append([[x, y, z(high, (x, y))] for x, y in p])
            for ring in [atom.exterior]+list(atom.interiors):
                p = list(ring.coords)
                for start, end in zip(p, p[1:]):
                    edges[tuple(sorted((tuple(start), tuple(end))))].append(j)
        for (start, end), sides in edges.items():
            p = (np.array(start)+end)*.5
            coefficients = ordered([c for j in sides for span in intervals[j] for c in span], p)
            for low, high in zip(coefficients, coefficients[1:]):
                mid = .5*(z(low, p)+z(high, p))
                occupied = [any(z(lo, p) < mid < z(hi, p) for lo, hi in intervals[j]) for j in sides]
                if not any(occupied) or (len(occupied) == 2 and occupied[0] == occupied[1]):
                    continue
                lower, upper = [z(low, q) for q in (start, end)], [z(high, q) for q in (start, end)]
                if any(lo > hi+1e-7 for lo, hi in zip(lower, upper)):
                    return None
                face = [[*start, lower[0]], [*end, lower[1]], [*end, upper[1]], [*start, upper[0]]]
                material = atoms[next(j for j, active in zip(sides, occupied) if active)].representative_point()
                d = np.array(end)-start
                outward = np.array([d[1], -d[0]])
                if outward@(np.array(material.coords[0])-p) > 0:
                    face.reverse()
                faces.append(face)
        return IFCFastTopology._closed_polygon_mesh(faces)

    @staticmethod
    def _clip_convex_mesh(mesh, origin, normal, keep_negative):
        """Clip a certified convex closed shell by a plane without solid CSG."""
        import numpy as np
        from shapely.geometry import MultiPoint
        from shapely.ops import triangulate
        points = np.asarray(mesh.get("vertices", []), dtype=float)
        if len(points) < 4:
            return None
        tolerance = max(1e-7, float(np.ptp(points, axis=0).max())*1e-10)
        normal = np.asarray(normal, dtype=float)
        normal /= np.linalg.norm(normal)
        origin = np.asarray(origin, dtype=float)
        original, oriented = [], []
        centre = points.mean(axis=0)
        for ids in mesh["faces"]:
            p = points[ids]
            n = np.cross(p, np.roll(p, -1, axis=0)).sum(axis=0)
            length = np.linalg.norm(n)
            if length < 1e-10:
                return None
            n /= length
            distance = (points-p[0])@n
            if distance.min() < -tolerance and distance.max() > tolerance:
                return None  # Non-convex shell: use the general kernel.
            if max(abs((p-p[0])@n)) > tolerance:
                return None
            if (centre-p[0])@n > 0:
                p = p[::-1]
            original.append(list(p))
            oriented.append(list(p))
        if IFCFastTopology._closed_polygon_mesh(original) is None:
            return None
        sign = -1. if keep_negative else 1.
        signed = (points-origin)@normal*sign
        if signed.min() >= -tolerance:
            return mesh
        if signed.max() < tolerance:
            return {"vertices": [], "faces": [], "edges": []}
        faces, cuts = [], []
        for polygon in oriented:
            result = []
            for a, b in zip(polygon, polygon[1:]+polygon[:1]):
                da, db = float((a-origin)@normal*sign), float((b-origin)@normal*sign)
                if da >= -tolerance:
                    result.append(a)
                if (da > tolerance and db < -tolerance) or (da < -tolerance and db > tolerance):
                    p = a+(b-a)*da/(da-db)
                    result.append(p)
                    cuts.append(p)
                elif abs(da) <= tolerance:
                    cuts.append(a)
            if len(result) >= 3:
                faces.append(result)
        if len(cuts) < 3:
            return None
        u = np.cross(normal, np.eye(3)[int(np.argmin(abs(normal)))])
        u /= np.linalg.norm(u)
        v = np.cross(normal, u)
        uv = [(float(p@u), float(p@v)) for p in cuts]
        cap = MultiPoint(uv).convex_hull
        triangles = triangulate(MultiPoint(uv))
        if cap.geom_type != "Polygon" or abs(sum(t.area for t in triangles)-cap.area) > max(1e-8, cap.area*1e-8):
            return None
        depth = float(origin@normal)
        for tri in triangles:
            p = list(tri.exterior.coords)[:-1]
            if tri.exterior.is_ccw == (sign > 0):
                p.reverse()
            faces.append([u*x+v*y+normal*depth for x, y in p])
        return IFCFastTopology._closed_polygon_mesh(faces)


    @staticmethod
    def _boolean_mesh(a: dict, b: dict, operation: str) -> dict:
        from topologicpy.Topology import Topology
        if a is None or b is None:
            raise ValueError("Unsupported IFC Boolean operand geometry")
        empty = {"vertices": [], "edges": [], "faces": []}
        if not a.get("vertices"):
            return b if operation == "UNION" else empty
        if not b.get("vertices"):
            return empty if operation == "INTERSECTION" else a
        if operation == "DIFFERENCE":
            prismatic = IFCFastTopology._prismatic_difference(a, b)
            if prismatic is not None:
                return prismatic
            columns = IFCFastTopology._column_difference(a, b)
            if columns is not None:
                return columns
        solids = [Topology.ByGeometry(vertices=m["vertices"], faces=m["faces"], topologyType="cell", silent=True) for m in (a,b)]
        if any(solid is None for solid in solids):
            raise ValueError("Could not construct IFC Boolean operand solid")
        methods = {"DIFFERENCE": Topology.Difference, "UNION": Topology.Union, "INTERSECTION": Topology.Intersect}
        if operation not in methods:
            raise ValueError("Unsupported IFC Boolean operator: " + operation)
        certified_empty = object()
        if Topology._IsTopologicCoreBackend():
            # Use the compiled operation directly: TopologicCore represents a
            # successful empty difference/intersection as None. Public wrapper
            # repair paths do not retain that distinction. Native exceptions
            # must still surface as failures, never as empty geometry.
            from topologicpy.Core import Core
            native_method = {"DIFFERENCE": "Difference", "UNION": "Union", "INTERSECTION": "Intersect"}[operation]
            try:
                result = Core.InstanceCall(solids[0], native_method, solids[1], False)
            except Exception as exc:
                raise ValueError("Native IFC Boolean operation failed: " + operation) from exc
            if result is None and operation in ("DIFFERENCE", "INTERSECTION"):
                return empty
        elif operation in ("DIFFERENCE", "INTERSECTION"):
            # The backend's ordinary wrappers use None for both failure and
            # emptiness. Request its explicit empty sentinel to keep these distinct.
            from OCC.Core.BRepAlgoAPI import BRepAlgoAPI_Cut, BRepAlgoAPI_Common
            result = solids[0]._binary_boolean(solids[1],
                BRepAlgoAPI_Cut if operation == "DIFFERENCE" else BRepAlgoAPI_Common,
                _empty_result=certified_empty)
        else:
            result = methods[operation](*solids, silent=True)
        if result is certified_empty:
            return empty
        if result is None:
            raise ValueError("Native IFC Boolean operation failed: " + operation)
        mesh = Topology.Geometry(result, triangulate=True, silent=True)
        if mesh is None:
            raise ValueError("Could not extract IFC Boolean result")
        return mesh

    @staticmethod
    def _mesh_from_item(item: IFCFastEntity,
                        entities: Dict[int, IFCFastEntity],
                        matrix: list,
                        circleSides: int = 24,
                        scale: float = 1.0) -> Optional[dict]:
        t = item.type
        if t == "IFCEXTRUDEDAREASOLID":
            return IFCFastTopology._extruded_area_solid_mesh(item, entities, matrix, circleSides, scale)
        if t == "IFCPOLYLINE":
            pts = IFCFastTopology._polyline_points(item, entities)
            if not pts:
                return None
            pts = [IFCFastTopology._transform_point(p, matrix, scale) for p in pts]
            return {"vertices": pts, "edges": [[i, i + 1] for i in range(len(pts) - 1)], "faces": []}
        if t == "IFCINDEXEDPOLYCURVE":
            pts, eds = IFCFastTopology._indexed_polycurve_points_edges(item, entities)
            if not pts:
                return None
            pts = [IFCFastTopology._transform_point(p, matrix, scale) for p in pts]
            return {"vertices": pts, "edges": eds, "faces": []}
        if t == "IFCBOUNDINGBOX":
            m = IFCFastTopology._bounding_box_mesh(item, entities)
            if m is None:
                return None
            m["vertices"] = [IFCFastTopology._transform_point(p, matrix, scale) for p in m["vertices"]]
            return m
        if t in ("IFCSHELLBASEDSURFACEMODEL", "IFCFACEBASEDSURFACEMODEL"):
            return IFCFastTopology._surface_model_mesh(item, entities, matrix, scale)
        if t in ("IFCFACETEDBREP", "IFCADVANCEDBREP"):
            shell = IFCFastTopology._entity_from_ref(item.args[0] if item.args else None, entities)
            return IFCFastTopology._shell_mesh(shell, entities, matrix, scale) if shell is not None else None
        if t in ("IFCCLOSEDSHELL", "IFCOPENSHELL", "IFCCONNECTEDFACESET"):
            return IFCFastTopology._shell_mesh(item, entities, matrix, scale)
        if t == "IFCMAPPEDITEM":
            return IFCFastTopology._mapped_item_mesh(item, entities, matrix, circleSides, scale)
        if t in ("IFCBOOLEANRESULT", "IFCBOOLEANCLIPPINGRESULT"):
            first = IFCFastTopology._entity_from_ref(item.args[1] if len(item.args) > 1 else None, entities)
            second = IFCFastTopology._entity_from_ref(item.args[2] if len(item.args) > 2 else None, entities)
            if first is None or second is None:
                raise ValueError("Missing IFC Boolean operand")
            a = IFCFastTopology._mesh_from_item(first, entities, matrix, circleSides, scale)
            if second.type in ("IFCHALFSPACESOLID", "IFCBOXEDHALFSPACE", "IFCPOLYGONALBOUNDEDHALFSPACE"):
                if str(item.args[0]).strip(".").upper() == "UNION":
                    raise ValueError("Cannot produce a finite mesh for an unbounded half-space union")
                b = IFCFastTopology._half_space_mesh(second, entities, matrix, scale, a)
            else:
                b = IFCFastTopology._mesh_from_item(second, entities, matrix, circleSides, scale)
            return IFCFastTopology._boolean_mesh(a, b, str(item.args[0]).strip(".").upper())
        return None

    @staticmethod
    def _half_space_mesh(item, entities, matrix, scale, operand):
        """Bound a clipping half-space outside the finite operand's full extent."""
        if operand is None:
            raise ValueError("Unsupported IFC clipping operand")
        if not operand.get("vertices"):
            return {"vertices": [], "edges": [], "faces": []}
        surface = IFCFastTopology._entity_from_ref(item.args[0], entities)
        if surface is None or surface.type != "IFCPLANE":
            raise ValueError("Only planar IFC clipping half-spaces are supported")
        frame = IFCFastTopology._matmul(matrix, IFCFastTopology._axis2placement_matrix(
            IFCFastTopology._entity_from_ref(surface.args[0], entities), entities))
        origin = IFCFastTopology._transform_point([0,0,0], frame, scale)
        axes = [IFCFastTopology._normalize([frame[i][j] for i in range(3)]) for j in range(3)]
        local = [[IFCFastTopology._dot([p[i]-origin[i] for i in range(3)], axis) for axis in axes] for p in operand["vertices"]]
        margin = max(1.0, max(max(p[i] for p in local)-min(p[i] for p in local) for i in range(3)))
        low = [min(p[i] for p in local)-margin for i in range(3)]
        high = [max(p[i] for p in local)+margin for i in range(3)]
        if item.args[1] is True:
            high[2] = 0.0
            low[2] = min(low[2], -margin)
        else:
            low[2] = 0.0
            high[2] = max(high[2], margin)
        points = [[x,y,z] for z in (low[2],high[2]) for x,y in ((low[0],low[1]),(high[0],low[1]),(high[0],high[1]),(low[0],high[1]))]
        mesh = {"vertices": [[origin[i]+sum(p[j]*axes[j][i] for j in range(3)) for i in range(3)] for p in points],
                "edges": [], "faces": [[0,1,2,3],[4,7,6,5],[0,4,5,1],[1,5,6,2],[2,6,7,3],[3,7,4,0]]}
        if item.type == "IFCBOXEDHALFSPACE":
            enclosure = IFCFastTopology._entity_from_ref(item.args[2], entities)
            box = IFCFastTopology._mesh_from_item(enclosure, entities, matrix, scale=scale) if enclosure else None
            return IFCFastTopology._boolean_mesh(mesh, box, "INTERSECTION")
        if item.type == "IFCPOLYGONALBOUNDEDHALFSPACE":
            boundary_frame = IFCFastTopology._matmul(matrix, IFCFastTopology._axis2placement_matrix(
                IFCFastTopology._entity_from_ref(item.args[2], entities), entities))
            inverse = IFCFastTopology._inverse_rigid_matrix(boundary_frame)
            # Work in IFC coordinates for the boundary extrusion, then scale once.
            heights = [IFCFastTopology._transform_point([v/scale for v in p], inverse)[2] for p in operand["vertices"]]
            z0, z1 = min(heights)-margin/scale, max(heights)+margin/scale
            boundary = IFCFastTopology._curve_points_local(IFCFastTopology._entity_from_ref(item.args[3], entities), entities)
            if not boundary:
                raise ValueError("Unsupported IFC half-space boundary")
            if IFCFastTopology._points_close(boundary[0], boundary[-1]):
                boundary = boundary[:-1]
            vertices = [IFCFastTopology._transform_point([p[0],p[1],z], boundary_frame, scale) for z in (z0,z1) for p in boundary]
            n = len(boundary)
            faces = [list(range(n)),list(range(n,2*n))] + [[i,(i+1)%n,(i+1)%n+n,i+n] for i in range(n)]
            prism = {"vertices": vertices, "edges": [], "faces": faces}
            clipped = IFCFastTopology._clip_convex_mesh(prism, origin, axes[2], item.args[1] is True)
            if clipped is not None:
                return clipped
            return IFCFastTopology._boolean_mesh(mesh, prism, "INTERSECTION")
        return mesh

    @staticmethod
    def _surface_model_mesh(item: IFCFastEntity, entities: Dict[int, IFCFastEntity], matrix: list, scale: float) -> Optional[dict]:
        meshes = []
        for ref in IFCFastTopology._refs_in_value(item.args[0] if item.args else None):
            shell = IFCFastTopology._entity_from_ref(ref, entities)
            if shell is not None:
                if shell.type in ("IFCCLOSEDSHELL", "IFCOPENSHELL", "IFCCONNECTEDFACESET"):
                    m = IFCFastTopology._shell_mesh(shell, entities, matrix, scale)
                    if m is not None:
                        meshes.append(m)
                elif shell.type in ("IFCFACE", "IFCADVANCEDFACE"):
                    m = IFCFastTopology._face_mesh(shell, entities, matrix, scale)
                    if m is not None:
                        meshes.append(m)
        return IFCFastTopology._merge_meshes(meshes, dedupe=True) if meshes else None

    @staticmethod
    def _shell_mesh(shell: IFCFastEntity, entities: Dict[int, IFCFastEntity], matrix: list, scale: float) -> Optional[dict]:
        if shell is None or not shell.args:
            return None
        meshes = []
        for ref in IFCFastTopology._refs_in_value(shell.args[0]):
            face = IFCFastTopology._entity_from_ref(ref, entities)
            if face is None or face.type not in ("IFCFACE", "IFCADVANCEDFACE"):
                raise ValueError("Unsupported IFC shell face")
            meshes.append(IFCFastTopology._face_mesh(face, entities, matrix, scale))
        return IFCFastTopology._merge_meshes(meshes, dedupe=True) if meshes else None

    @staticmethod
    def _loops_mesh(loops: list) -> dict:
        """Preserve inner bounds by triangulating a native face only when needed."""
        cleaned = []
        for loop in loops:
            pts = []
            for point in loop:
                if not pts or not IFCFastTopology._points_close(pts[-1], point):
                    pts.append(point)
            if len(pts) > 1 and IFCFastTopology._points_close(pts[0], pts[-1]):
                pts.pop()
            if len(pts) < 3:
                raise ValueError("Invalid IFC face boundary")
            cleaned.append(pts)
        if len(cleaned) == 1:
            return {"vertices": cleaned[0], "edges": [], "faces": [list(range(len(cleaned[0])))]}
        from topologicpy.Vertex import Vertex
        from topologicpy.Wire import Wire
        from topologicpy.Face import Face
        from topologicpy.Topology import Topology
        wires = [Wire.ByVertices([Vertex.ByCoordinates(*p) for p in loop], close=True) for loop in cleaned]
        face = Face.ByWires(wires[0], wires[1:], silent=True)
        if face is None:
            raise ValueError("Could not construct IFC face with inner bounds")
        mesh = Topology.Geometry(face, triangulate=True, silent=True)
        if not mesh or not mesh.get("faces"):
            raise ValueError("Could not triangulate IFC face with inner bounds")
        return mesh

    @staticmethod
    def _face_mesh(face: IFCFastEntity, entities: Dict[int, IFCFastEntity], matrix: list, scale: float) -> Optional[dict]:
        if face.type == "IFCADVANCEDFACE":
            surface = IFCFastTopology._entity_from_ref(face.args[1] if len(face.args) > 1 else None, entities)
            if surface is None or surface.type != "IFCPLANE":
                raise ValueError("Curved IfcAdvancedFace surfaces are not supported; refusing a planar approximation")
        loops = IFCFastTopology._face_loops(face, entities)
        if not loops:
            raise ValueError("IFC face has no valid boundary")
        mesh = IFCFastTopology._loops_mesh([[IFCFastTopology._transform_point(p, matrix, scale) for p in loop] for loop in loops])
        if face.type == "IFCADVANCEDFACE" and len(face.args) > 2 and face.args[2] is False:
            mesh["faces"] = [list(reversed(f)) for f in mesh["faces"]]
        return mesh

    @staticmethod
    def _face_loops(face: IFCFastEntity, entities: Dict[int, IFCFastEntity]) -> list:
        loops = []
        outer = None
        for bound_ref in IFCFastTopology._refs_in_value(face.args[0] if face.args else None):
            bound = IFCFastTopology._entity_from_ref(bound_ref, entities)
            if bound is None or bound.type not in ("IFCFACEOUTERBOUND", "IFCFACEBOUND"):
                continue
            loop_ent = IFCFastTopology._entity_from_ref(bound.args[0] if bound.args else None, entities)
            if loop_ent is None:
                continue
            pts = []
            if loop_ent.type == "IFCPOLYLOOP":
                for p_ref in IFCFastTopology._refs_in_value(loop_ent.args[0] if loop_ent.args else None):
                    p = IFCFastTopology._cartesian_point(p_ref, entities)
                    if p is not None:
                        pts.append(p)
            elif loop_ent.type == "IFCEDGELOOP":
                # Minimal edge-loop support. Curved edges are approximated by endpoints.
                for edge_ref in IFCFastTopology._refs_in_value(loop_ent.args[0] if loop_ent.args else None):
                    edge = IFCFastTopology._entity_from_ref(edge_ref, entities)
                    pts.extend(IFCFastTopology._edge_points(edge, entities))
            if len(bound.args) > 1 and bound.args[1] is False:
                pts.reverse()
            if len(pts) >= 3:
                if bound.type == "IFCFACEOUTERBOUND":
                    outer = pts
                else:
                    loops.append(pts)
        if outer is None and loops:
            # IFC permits faces whose bounds are all IfcFaceBound. The set is
            # unordered; for planar polygonal faces the enclosing loop has the
            # greatest area vector magnitude (independent of plane or winding).
            def area_vector_length(loop):
                vector = [0.0, 0.0, 0.0]
                for a, b in zip(loop, loop[1:]+loop[:1]):
                    cross = IFCFastTopology._cross(a, b)
                    vector = [vector[i]+cross[i] for i in range(3)]
                return IFCFastTopology._norm(vector)
            outer = max(loops, key=area_vector_length)
            loops = [loop for loop in loops if loop is not outer]
        return ([outer] if outer is not None else []) + loops

    @staticmethod
    def _edge_points(edge: Optional[IFCFastEntity], entities: Dict[int, IFCFastEntity]) -> list:
        if edge is None:
            return []
        if edge.type == "IFCORIENTEDEDGE":
            edge_element = IFCFastTopology._entity_from_ref(edge.args[2] if len(edge.args) > 2 else None, entities)
            pts = IFCFastTopology._edge_points(edge_element, entities)
            orientation = edge.args[3] if len(edge.args) > 3 else True
            return pts if orientation is not False else list(reversed(pts))
        if edge.type in ("IFCEDGE", "IFCEDGECURVE"):
            a = IFCFastTopology._vertex_point(edge.args[0] if len(edge.args) > 0 else None, entities)
            b = IFCFastTopology._vertex_point(edge.args[1] if len(edge.args) > 1 else None, entities)
            if edge.type == "IFCEDGECURVE":
                curve = IFCFastTopology._entity_from_ref(edge.args[2] if len(edge.args)>2 else None, entities)
                if curve is None:
                    raise ValueError("Missing IFC edge curve")
                if curve.type != "IFCLINE":
                    points = IFCFastTopology._curve_points_local(curve, entities)
                    if not points or a is None or b is None:
                        raise ValueError("Unsupported IFC edge curve: " + curve.type)
                    if len(edge.args)>3 and edge.args[3] is False:
                        points.reverse()
                    if not IFCFastTopology._points_close(points[0],a) or not IFCFastTopology._points_close(points[-1],b):
                        raise ValueError("Unsupported trimmed IFC edge curve")
                    return points
            return [p for p in [a, b] if p is not None]
        return []

    @staticmethod
    def _vertex_point(v: Any, entities: Dict[int, IFCFastEntity]) -> Optional[list]:
        vertex = IFCFastTopology._entity_from_ref(v, entities)
        if vertex is None:
            return None
        if vertex.type == "IFCVERTEXPOINT":
            return IFCFastTopology._cartesian_point(vertex.args[0] if vertex.args else None, entities)
        return None

    @staticmethod
    def _mapped_item_mesh(item: IFCFastEntity, entities: Dict[int, IFCFastEntity], matrix: list, circleSides: int, scale: float) -> Optional[dict]:
        """
        Returns mesh data for an IfcMappedItem.

        The correct transform chain is:

            product/local placement * mapping target * inverse(mapping source origin)

        The previous version used:

            product/local placement * mapping target * mapping source origin

        That is wrong when the representation map has a non-identity
        MappingOrigin. It typically shows up first in repeated components such
        as window panes, mullions, curtain-wall parts, and partition modules.
        """
        mapping_source = IFCFastTopology._entity_from_ref(item.args[0] if len(item.args) > 0 else None, entities)
        operator = IFCFastTopology._entity_from_ref(item.args[1] if len(item.args) > 1 else None, entities)
        if mapping_source is None or mapping_source.type != "IFCREPRESENTATIONMAP":
            return None

        origin = IFCFastTopology._entity_from_ref(mapping_source.args[0] if len(mapping_source.args) > 0 else None, entities)
        origin_matrix = IFCFastTopology._axis2placement_matrix(origin, entities)
        origin_inverse = IFCFastTopology._inverse_rigid_matrix(origin_matrix)

        source_rep = IFCFastTopology._entity_from_ref(mapping_source.args[1] if len(mapping_source.args) > 1 else None, entities)
        op_matrix = IFCFastTopology._mapped_item_operator_matrix(operator, entities)

        new_matrix = IFCFastTopology._matmul(matrix, IFCFastTopology._matmul(op_matrix, origin_inverse))

        meshes = []
        if source_rep is not None and source_rep.type == "IFCSHAPEREPRESENTATION":
            for ref in IFCFastTopology._refs_in_value(source_rep.args[3] if len(source_rep.args) > 3 else None):
                child = IFCFastTopology._entity_from_ref(ref, entities)
                if child is not None:
                    m = IFCFastTopology._mesh_from_item(child, entities, new_matrix, circleSides, scale)
                    if m is not None:
                        meshes.append(m)
        return IFCFastTopology._merge_meshes(meshes, dedupe=True) if meshes else None

    # ------------------------------------------------------------------
    # Swept solids / profiles
    # ------------------------------------------------------------------

    @staticmethod
    def _extruded_area_solid_mesh(solid: IFCFastEntity, entities: Dict[int, IFCFastEntity], product_matrix: list, circleSides: int, scale: float) -> Optional[dict]:
        if len(solid.args) < 4:
            return None
        profile = IFCFastTopology._entity_from_ref(solid.args[0], entities)
        position = IFCFastTopology._axis2placement_matrix(IFCFastTopology._entity_from_ref(solid.args[1], entities), entities)
        direction = IFCFastTopology._direction(solid.args[2], entities, default=[0.0, 0.0, 1.0])
        depth = IFCFastTopology._as_float(solid.args[3], 0.0)
        if profile is None or abs(depth) <= 1e-12:
            return None
        loops = IFCFastTopology._profile_loops(profile, entities, circleSides)
        if not loops:
            return None
        if len(loops) > 1:
            direction = IFCFastTopology._normalize(IFCFastTopology._normalise_point(direction))
            offset = [v * depth for v in direction]
            matrix = IFCFastTopology._matmul(product_matrix, position)
            bottom = []
            top = []
            sides = []
            for loop in loops:
                if IFCFastTopology._points_close(loop[0], loop[-1]):
                    loop = loop[:-1]
                low = [IFCFastTopology._transform_point(p, matrix, scale) for p in loop]
                high = [IFCFastTopology._transform_point([p[i]+offset[i] for i in range(3)], matrix, scale) for p in loop]
                bottom.append(low)
                top.append(high)
                for i in range(len(low)):
                    j = (i+1) % len(low)
                    sides.append({"vertices": [low[i], low[j], high[j], high[i]], "edges": [], "faces": [[0,1,2,3]]})
            return IFCFastTopology._merge_meshes([IFCFastTopology._loops_mesh(bottom), IFCFastTopology._loops_mesh(top)] + sides, dedupe=True)
        outer = loops[0]
        if len(outer) > 1 and IFCFastTopology._points_close(outer[0], outer[-1]):
            outer = outer[:-1]
        if len(outer) < 3:
            return None
        direction = IFCFastTopology._normalize(IFCFastTopology._normalise_point(direction))
        if IFCFastTopology._norm(direction) <= 1e-12:
            direction = [0.0, 0.0, 1.0]
        top_offset = [direction[0] * depth, direction[1] * depth, direction[2] * depth]
        n = len(outer)
        local_vertices = [IFCFastTopology._normalise_point(p) for p in outer]
        local_vertices += [[p[0] + top_offset[0], p[1] + top_offset[1], p[2] + top_offset[2]] for p in local_vertices[:n]]
        matrix = IFCFastTopology._matmul(product_matrix, position)
        vertices = [IFCFastTopology._transform_point(p, matrix, scale) for p in local_vertices]
        faces = [list(range(n)), list(range(2 * n - 1, n - 1, -1))]
        for i in range(n):
            j = (i + 1) % n
            faces.append([i, j, j + n, i + n])
        return {"vertices": vertices, "edges": [], "faces": faces}

    @staticmethod
    def _profile_loops(profile: IFCFastEntity, entities: Dict[int, IFCFastEntity], circleSides: int) -> list:
        t = profile.type
        if t == "IFCARBITRARYCLOSEDPROFILEDEF":
            curve = IFCFastTopology._entity_from_ref(profile.args[2] if len(profile.args) > 2 else None, entities)
            pts = IFCFastTopology._curve_points_local(curve, entities, circleSides)
            return [pts] if pts else []
        if t == "IFCARBITRARYPROFILEDEFWITHVOIDS":
            outer_curve = IFCFastTopology._entity_from_ref(profile.args[2] if len(profile.args) > 2 else None, entities)
            pts = IFCFastTopology._curve_points_local(outer_curve, entities, circleSides)
            loops = [pts] if pts else []
            for ref in IFCFastTopology._refs_in_value(profile.args[3] if len(profile.args) > 3 else None):
                inner = IFCFastTopology._curve_points_local(IFCFastTopology._entity_from_ref(ref, entities), entities, circleSides)
                if not inner:
                    raise ValueError("Unsupported IFC profile void curve")
                loops.append(inner)
            return loops
        if t == "IFCRECTANGLEPROFILEDEF":
            xdim = IFCFastTopology._as_float(profile.args[3] if len(profile.args) > 3 else 0.0, 0.0)
            ydim = IFCFastTopology._as_float(profile.args[4] if len(profile.args) > 4 else 0.0, 0.0)
            hx, hy = xdim * 0.5, ydim * 0.5
            pts = [[-hx, -hy, 0.0], [hx, -hy, 0.0], [hx, hy, 0.0], [-hx, hy, 0.0]]
            pos = IFCFastTopology._axis2placement_matrix(IFCFastTopology._entity_from_ref(profile.args[2] if len(profile.args) > 2 else None, entities), entities)
            return [[IFCFastTopology._transform_point(p, pos) for p in pts]]
        if t == "IFCCIRCLEPROFILEDEF":
            radius = IFCFastTopology._as_float(profile.args[3] if len(profile.args) > 3 else 0.0, 0.0)
            if radius <= 0:
                return []
            sides = max(8, int(circleSides or 24))
            pts = [[radius * math.cos(2 * math.pi * i / sides), radius * math.sin(2 * math.pi * i / sides), 0.0] for i in range(sides)]
            pos = IFCFastTopology._axis2placement_matrix(IFCFastTopology._entity_from_ref(profile.args[2] if len(profile.args) > 2 else None, entities), entities)
            return [[IFCFastTopology._transform_point(p, pos) for p in pts]]
        return []

    @staticmethod
    def _plane_angle_unit_scale(entities):
        """Resolve assigned curve parameters to radians (unitless fragments use radians)."""
        def factor(unit, seen):
            if unit is None or unit.id in seen:
                raise ValueError("Invalid IFC plane angle unit")
            if len(unit.args) < 2 or unit.args[1] != "PLANEANGLEUNIT":
                raise ValueError("Invalid IFC plane angle conversion unit")
            if unit.type == "IFCSIUNIT" and unit.args[2] is None and unit.args[3] == "RADIAN":
                return 1.0
            if unit.type == "IFCCONVERSIONBASEDUNIT":
                measure = IFCFastTopology._entity_from_ref(unit.args[3], entities)
                if measure is None or measure.type != "IFCMEASUREWITHUNIT":
                    raise ValueError("Invalid IFC plane angle conversion factor")
                value = IFCFastTopology._validated_scale(IFCFastTopology._as_float(measure.args[0]))
                base = IFCFastTopology._entity_from_ref(measure.args[1], entities)
                return value * factor(base, seen | {unit.id})
            raise ValueError("Unsupported IFC plane angle unit")

        projects = [e for e in entities.values() if e.type == "IFCPROJECT"]
        assignments = [IFCFastTopology._entity_from_ref(e.args[8], entities)
                       for e in projects if len(e.args) > 8 and e.args[8] is not None]
        if not projects:
            assignments = [e for e in entities.values() if e.type == "IFCUNITASSIGNMENT"]
        factors = []
        for assignment in assignments:
            if assignment is None or assignment.type != "IFCUNITASSIGNMENT":
                raise ValueError("Invalid IFC project unit assignment")
            for ref in IFCFastTopology._refs_in_value(assignment.args[0]):
                unit = IFCFastTopology._entity_from_ref(ref, entities)
                if unit is not None and len(unit.args) > 1 and unit.args[1] == "PLANEANGLEUNIT":
                    factors.append(factor(unit, set()))
        if factors and any(not math.isclose(v, factors[0], rel_tol=1e-12) for v in factors):
            raise ValueError("Conflicting IFC plane angle units")
        return factors[0] if factors else 1.0

    @staticmethod
    def _curve_points_local(curve: Optional[IFCFastEntity], entities: Dict[int, IFCFastEntity], circleSides: int = 24, _active=None) -> list:
        if curve is None:
            return []
        active = set() if _active is None else _active
        if curve.id in active:
            raise ValueError("Cyclic IFC composite curve")
        active = active | {curve.id}
        if curve.type == "IFCCOMPOSITECURVE":
            points = []
            for ref in IFCFastTopology._refs_in_value(curve.args[0]):
                segment = IFCFastTopology._entity_from_ref(ref, entities)
                if segment is None or segment.type != "IFCCOMPOSITECURVESEGMENT":
                    raise ValueError("Invalid IFC composite curve segment")
                parent = IFCFastTopology._entity_from_ref(segment.args[2], entities)
                part = IFCFastTopology._curve_points_local(parent, entities, circleSides, active)
                if not part:
                    raise ValueError("Unsupported IFC composite curve segment")
                if segment.args[1] is False:
                    part = list(reversed(part))
                if points:
                    if not IFCFastTopology._points_close(points[-1], part[0]):
                        raise ValueError("Disconnected IFC composite curve segments")
                    part = part[1:]
                points.extend(part)
            return points
        if curve.type == "IFCTRIMMEDCURVE":
            basis = IFCFastTopology._entity_from_ref(curve.args[0], entities)
            if basis is None or basis.type != "IFCCIRCLE":
                return []
            frame = IFCFastTopology._axis2placement_matrix(
                IFCFastTopology._entity_from_ref(basis.args[0], entities), entities)
            inverse = IFCFastTopology._inverse_rigid_matrix(frame)
            radius = IFCFastTopology._as_float(basis.args[1])
            if radius <= 0:
                raise ValueError("Invalid IFC trimmed circle radius")
            angle_scale = IFCFastTopology._plane_angle_unit_scale(entities)

            def parameter(values):
                # Honour the preferred trimming representation when both are present.
                prefer_parameter = len(curve.args) > 4 and curve.args[4] == "PARAMETER"
                ordered = sorted(values, key=lambda v: (isinstance(v, tuple) and v[0] == "REF") == prefer_parameter)
                for value in ordered:
                    point = IFCFastTopology._entity_from_ref(value, entities)
                    if point is not None and point.type == "IFCCARTESIANPOINT":
                        local = IFCFastTopology._transform_point(
                            IFCFastTopology._normalise_point(point.args[0]), inverse)
                        return math.atan2(local[1], local[0])
                    if isinstance(value, (int, float)) or (isinstance(value, tuple) and value[0] == "CALL"):
                        return IFCFastTopology._as_float(value) * angle_scale
                raise ValueError("Unsupported IFC circle trimming parameter")

            start, end = parameter(curve.args[1]), parameter(curve.args[2])
            sweep = (end - start) % (2 * math.pi)
            if curve.args[3] is False:
                sweep = -((start - end) % (2 * math.pi))
            count = max(1, math.ceil(abs(sweep) * max(8, int(circleSides)) / (2 * math.pi)))
            return [IFCFastTopology._transform_point(
                [radius * math.cos(start + sweep*i/count),
                 radius * math.sin(start + sweep*i/count), 0], frame)
                for i in range(count + 1)]
        if curve.type == "IFCPOLYLINE":
            return IFCFastTopology._polyline_points(curve, entities)
        if curve.type == "IFCINDEXEDPOLYCURVE":
            pts, edges = IFCFastTopology._indexed_polycurve_points_edges(curve, entities)
            ordered = []
            for a, b in edges:
                if ordered and not IFCFastTopology._points_close(ordered[-1], pts[a]):
                    raise ValueError("Disconnected IfcIndexedPolyCurve segments")
                if not ordered:
                    ordered.append(pts[a])
                ordered.append(pts[b])
            return ordered
        return []

    @staticmethod
    def _polyline_points(polyline: IFCFastEntity, entities: Dict[int, IFCFastEntity]) -> list:
        pts = []
        for r in IFCFastTopology._refs_in_value(polyline.args[0] if polyline.args else None):
            p = IFCFastTopology._cartesian_point(r, entities)
            if p is not None:
                pts.append(p)
        return pts

    @staticmethod
    def _arc_points(a, b, c, circleSides=24):
        u = [b[i]-a[i] for i in range(3)]
        v = [c[i]-a[i] for i in range(3)]
        normal = IFCFastTopology._cross(u, v)
        norm2 = IFCFastTopology._dot(normal, normal)
        if norm2 <= 1e-24:
            raise ValueError("Collinear IFC arc points")
        vx = IFCFastTopology._cross(v, normal)
        nx = IFCFastTopology._cross(normal, u)
        center = [a[i]+(IFCFastTopology._dot(u,u)*vx[i]+IFCFastTopology._dot(v,v)*nx[i])/(2*norm2) for i in range(3)]
        x = IFCFastTopology._normalize([a[i]-center[i] for i in range(3)])
        y = IFCFastTopology._cross(IFCFastTopology._normalize(normal), x)
        radius = IFCFastTopology._norm([a[i]-center[i] for i in range(3)])
        def angle(p):
            delta = [p[i]-center[i] for i in range(3)]
            return math.atan2(IFCFastTopology._dot(delta,y), IFCFastTopology._dot(delta,x)) % (2*math.pi)
        mid, end = angle(b), angle(c)
        if mid > end:
            mid -= 2*math.pi
            end -= 2*math.pi
        points = [a]
        for start, finish in ((0.0,mid),(mid,end)):
            count = max(1, math.ceil(abs(finish-start)*max(8,circleSides)/(2*math.pi)))
            points.extend([[center[j]+radius*(math.cos(start+(finish-start)*i/count)*x[j]+math.sin(start+(finish-start)*i/count)*y[j]) for j in range(3)] for i in range(1,count+1)])
        points[-1] = c
        return points

    @staticmethod
    def _indexed_polycurve_points_edges(curve: IFCFastEntity, entities: Dict[int, IFCFastEntity]) -> tuple[list, list]:
        point_list = IFCFastTopology._entity_from_ref(curve.args[0] if curve.args else None, entities)
        if point_list is None:
            return [], []
        pts = []
        coords = point_list.args[0] if point_list.args else []
        if isinstance(coords, list):
            for c in coords:
                if isinstance(c, list):
                    pts.append(IFCFastTopology._normalise_point(c))
        edges = [[i, i + 1] for i in range(len(pts) - 1)]
        segments = curve.args[1] if len(curve.args) > 1 else None
        if isinstance(segments, list) and segments:
            edges = []
            for seg in segments:
                if not (isinstance(seg, tuple) and len(seg) == 3 and seg[0] == "CALL"):
                    raise ValueError("Invalid IFC indexed curve segment")
                idxs = [int(x)-1 for x in seg[2][0]]
                if any(i < 0 or i >= len(coords) for i in idxs):
                    raise ValueError("IFC indexed curve point index out of range")
                if seg[1] == "IFCLINEINDEX":
                    edges.extend([[a,b] for a,b in zip(idxs[:-1],idxs[1:])])
                elif seg[1] == "IFCARCINDEX" and len(idxs) == 3:
                    arc = IFCFastTopology._arc_points(*(pts[i] for i in idxs))
                    chain = [idxs[0]]
                    for point in arc[1:-1]:
                        chain.append(len(pts))
                        pts.append(point)
                    chain.append(idxs[-1])
                    edges.extend([[a,b] for a,b in zip(chain[:-1],chain[1:])])
                else:
                    raise ValueError("Unsupported IFC indexed curve segment: " + str(seg[1]))
        return pts, edges

    @staticmethod
    def _bounding_box_mesh(box: IFCFastEntity, entities: Dict[int, IFCFastEntity]) -> Optional[dict]:
        corner = IFCFastTopology._cartesian_point(box.args[0] if len(box.args) > 0 else None, entities)
        if corner is None or len(box.args) < 4:
            return None
        xdim = IFCFastTopology._as_float(box.args[1], 0.0)
        ydim = IFCFastTopology._as_float(box.args[2], 0.0)
        zdim = IFCFastTopology._as_float(box.args[3], 0.0)
        x, y, z = IFCFastTopology._normalise_point(corner)
        verts = [
            [x, y, z], [x + xdim, y, z], [x + xdim, y + ydim, z], [x, y + ydim, z],
            [x, y, z + zdim], [x + xdim, y, z + zdim], [x + xdim, y + ydim, z + zdim], [x, y + ydim, z + zdim],
        ]
        faces = [[0, 1, 2, 3], [4, 7, 6, 5], [0, 4, 5, 1], [1, 5, 6, 2], [2, 6, 7, 3], [3, 7, 4, 0]]
        return {"vertices": verts, "edges": [], "faces": faces}

    # ------------------------------------------------------------------
    # Placement / transforms
    # ------------------------------------------------------------------

    @staticmethod
    def _product_placement_matrix(
        product: IFCFastEntity,
        entities: Dict[int, IFCFastEntity],
        cache: dict = None,
    ) -> list:
        cache_key = ("product", product.id) if product is not None else None
        if isinstance(cache, dict) and cache_key in cache:
            return cache[cache_key]
        placement = IFCFastTopology._entity_from_ref(
            product.args[5] if len(product.args) > 5 else None,
            entities,
        )
        matrix = IFCFastTopology._local_placement_matrix(
            placement,
            entities,
            cache=cache,
        )
        if isinstance(cache, dict) and cache_key is not None:
            cache[cache_key] = matrix
        return matrix

    @staticmethod
    def _local_placement_matrix(
        placement: Optional[IFCFastEntity],
        entities: Dict[int, IFCFastEntity],
        cache: dict = None,
    ) -> list:
        if placement is None or placement.type != "IFCLOCALPLACEMENT":
            return IFCFastTopology._identity()
        cache_key = ("local", placement.id)
        if isinstance(cache, dict) and cache_key in cache:
            return cache[cache_key]
        parent = IFCFastTopology._entity_from_ref(
            placement.args[0] if len(placement.args) > 0 else None,
            entities,
        )
        rel = IFCFastTopology._entity_from_ref(
            placement.args[1] if len(placement.args) > 1 else None,
            entities,
        )
        parent_matrix = (
            IFCFastTopology._local_placement_matrix(parent, entities, cache=cache)
            if parent is not None
            else IFCFastTopology._identity()
        )
        rel_matrix = IFCFastTopology._axis2placement_matrix(rel, entities)
        matrix = IFCFastTopology._matmul(parent_matrix, rel_matrix)
        if isinstance(cache, dict):
            cache[cache_key] = matrix
        return matrix

    @staticmethod
    def _axis2placement_matrix(axis: Optional[IFCFastEntity], entities: Dict[int, IFCFastEntity]) -> list:
        if axis is None:
            return IFCFastTopology._identity()
        if axis.type == "IFCAXIS2PLACEMENT3D":
            loc = IFCFastTopology._cartesian_point(axis.args[0] if len(axis.args) > 0 else None, entities) or [0.0, 0.0, 0.0]
            z = IFCFastTopology._direction(axis.args[1] if len(axis.args) > 1 else None, entities, default=[0.0, 0.0, 1.0])
            x = IFCFastTopology._direction(axis.args[2] if len(axis.args) > 2 else None, entities, default=[1.0, 0.0, 0.0])
            z = IFCFastTopology._normalize(IFCFastTopology._normalise_point(z))
            x = IFCFastTopology._normalize(IFCFastTopology._normalise_point(x))
            y = IFCFastTopology._normalize(IFCFastTopology._cross(z, x))
            x = IFCFastTopology._normalize(IFCFastTopology._cross(y, z))
            loc = IFCFastTopology._normalise_point(loc)
            return [[x[0], y[0], z[0], loc[0]], [x[1], y[1], z[1], loc[1]], [x[2], y[2], z[2], loc[2]], [0.0, 0.0, 0.0, 1.0]]
        if axis.type == "IFCAXIS2PLACEMENT2D":
            loc = IFCFastTopology._cartesian_point(axis.args[0] if len(axis.args) > 0 else None, entities) or [0.0, 0.0, 0.0]
            x = IFCFastTopology._direction(axis.args[1] if len(axis.args) > 1 else None, entities, default=[1.0, 0.0, 0.0])
            x = IFCFastTopology._normalize(IFCFastTopology._normalise_point(x))
            y = [-x[1], x[0], 0.0]
            loc = IFCFastTopology._normalise_point(loc)
            return [[x[0], y[0], 0.0, loc[0]], [x[1], y[1], 0.0, loc[1]], [0.0, 0.0, 1.0, loc[2]], [0.0, 0.0, 0.0, 1.0]]
        return IFCFastTopology._identity()

    @staticmethod
    def _mapped_item_operator_matrix(operator: Optional[IFCFastEntity], entities: Dict[int, IFCFastEntity]) -> list:
        if operator is None:
            return IFCFastTopology._identity()

        if operator.type in ("IFCCARTESIANTRANSFORMATIONOPERATOR3D", "IFCCARTESIANTRANSFORMATIONOPERATOR3DNONUNIFORM"):
            raw_axis1 = IFCFastTopology._direction(operator.args[0] if len(operator.args) > 0 else None, entities, default=[1.0, 0.0, 0.0])
            raw_axis2 = IFCFastTopology._direction(operator.args[1] if len(operator.args) > 1 else None, entities, default=None)
            origin = IFCFastTopology._cartesian_point(operator.args[2] if len(operator.args) > 2 else None, entities) or [0.0, 0.0, 0.0]
            s1 = IFCFastTopology._as_float(operator.args[3] if len(operator.args) > 3 else 1.0, 1.0)
            raw_axis3 = IFCFastTopology._direction(operator.args[4] if len(operator.args) > 4 else None, entities, default=None)
            s2 = IFCFastTopology._as_float(operator.args[5] if len(operator.args) > 5 else s1, s1)
            s3 = IFCFastTopology._as_float(operator.args[6] if len(operator.args) > 6 else s1, s1)

            x = IFCFastTopology._normalize(IFCFastTopology._normalise_point(raw_axis1 or [1.0, 0.0, 0.0]))
            if raw_axis2 is not None:
                y = IFCFastTopology._normalize(IFCFastTopology._normalise_point(raw_axis2))
            elif raw_axis3 is not None:
                z_tmp = IFCFastTopology._normalize(IFCFastTopology._normalise_point(raw_axis3))
                y = IFCFastTopology._normalize(IFCFastTopology._cross(z_tmp, x))
            else:
                y = [0.0, 1.0, 0.0]

            if raw_axis3 is not None:
                z = IFCFastTopology._normalize(IFCFastTopology._normalise_point(raw_axis3))
            else:
                z = IFCFastTopology._normalize(IFCFastTopology._cross(x, y))

            y = IFCFastTopology._normalize(IFCFastTopology._cross(z, x))
            x = IFCFastTopology._normalize(IFCFastTopology._cross(y, z))

            o = IFCFastTopology._normalise_point(origin)
            return [
                [x[0] * s1, y[0] * s2, z[0] * s3, o[0]],
                [x[1] * s1, y[1] * s2, z[1] * s3, o[1]],
                [x[2] * s1, y[2] * s2, z[2] * s3, o[2]],
                [0.0, 0.0, 0.0, 1.0],
            ]

        if operator.type == "IFCCARTESIANTRANSFORMATIONOPERATOR2D":
            raw_axis1 = IFCFastTopology._direction(operator.args[0] if len(operator.args) > 0 else None, entities, default=[1.0, 0.0, 0.0])
            raw_axis2 = IFCFastTopology._direction(operator.args[1] if len(operator.args) > 1 else None, entities, default=None)
            origin = IFCFastTopology._cartesian_point(operator.args[2] if len(operator.args) > 2 else None, entities) or [0.0, 0.0, 0.0]
            s1 = IFCFastTopology._as_float(operator.args[3] if len(operator.args) > 3 else 1.0, 1.0)
            x = IFCFastTopology._normalize(IFCFastTopology._normalise_point(raw_axis1 or [1.0, 0.0, 0.0]))
            if raw_axis2 is None:
                y = [-x[1], x[0], 0.0]
            else:
                y = IFCFastTopology._normalize(IFCFastTopology._normalise_point(raw_axis2))
            o = IFCFastTopology._normalise_point(origin)
            return [
                [x[0] * s1, y[0] * s1, 0.0, o[0]],
                [x[1] * s1, y[1] * s1, 0.0, o[1]],
                [0.0, 0.0, s1, o[2]],
                [0.0, 0.0, 0.0, 1.0],
            ]

        return IFCFastTopology._identity()

